//! Generated by steelix from `python -m json` and the modules of its project.

#![allow(non_snake_case, unused_variables, unused_assignments)]
#![allow(clippy::never_loop, clippy::approx_constant, clippy::if_same_then_else)]
#![allow(clippy::too_many_arguments, clippy::doc_lazy_continuation)]
#![allow(
    clippy::while_immutable_condition,
    clippy::eq_op,
    clippy::nonminimal_bool
)]
#![allow(clippy::overly_complex_bool_expr, clippy::collapsible_if)]
#![allow(clippy::module_inception)]

mod json;

use steelix_runtime::NativeModule;

/// The project's modules: `import` runs their transpiled code instead of
/// their Python source.
const MODULES: &[NativeModule] = &[
    NativeModule::package("json", json::exec_module),
    NativeModule::module("json.__main__", json::__main__::exec_module),
    NativeModule::module("json.decoder", json::decoder::exec_module),
    NativeModule::module("json.encoder", json::encoder::exec_module),
    NativeModule::module("json.scanner", json::scanner::exec_module),
    NativeModule::module("json.tool", json::tool::exec_module),
];

fn main() -> std::process::ExitCode {
    let script = steelix_runtime::script!("json/__main__.py");
    steelix_runtime::embed::run_module(&script, MODULES, "json.__main__")
}
